"""Local synthetic outcome export checks; fixture generated by the matching JS test."""
import copy
import io
import json
from pathlib import Path
import sys
import unittest
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from pypdf import PdfReader
from screening_report import build_pdf,case_assessment_summary,ReportExportError
ROOT=Path(__file__).resolve().parents[1]
WORK=ROOT/'work'/'pre-api-hardening'
def fixture(name='current'):return json.loads((WORK/f'assessment-{name}.json').read_text())
def pages(report):return [' '.join(p.extract_text().split()) for p in PdfReader(io.BytesIO(build_pdf(report))).pages]

class AssessmentReports(unittest.TestCase):
    def test_effective_outcome_and_scope_on_cover_then_readable_record(self):
        report=fixture();result=pages(report)
        for value in ('EXECUTIVE REVIEW / REVIEW RECORDED','Next steps','Report reference: synthetic-case-review-example'):
            self.assertIn(value,result[0])
        for value in ('Case review outcome','Demonstration reviewer','Reason and follow-up','Next review: 16 Oct 2026','not client approval','not authenticated','Outcome history: 2 saved revisions'):
            self.assertIn(value,result[1])
        self.assertIn('01 / Official checks',result[2])
    def test_changed_evidence_reopens_earlier_conclusion_in_pdf(self):
        result=pages(fixture('stale'));self.assertIn('REVIEW NEEDS UPDATING',result[0]);body='\n'.join(result)
        for value in ('Previous recorded outcome: Review recorded','Evidence or identity decisions have changed','Previous reason and follow-up','United States','check is incomplete'):
            self.assertIn(value,body)
    def test_full_evidence_keeps_every_revision_and_scope_at_the_time(self):
        report=fixture();report['reportDetail']='full';body='\n'.join(pages(report))
        for value in ('Outcome history','1. Needs information','2. Review recorded','The EU check failed','Outstanding when recorded','Scope when recorded','Findings and scope acknowledged: No','Findings and scope acknowledged: Yes'):
            self.assertIn(value,body)
        for event in report['assessmentLog']:self.assertIn(event['id'],body)
    def test_pdf_table_presentation_does_not_stale_original_research(self):
        report=fixture('pdf-payload');self.assertFalse(case_assessment_summary(report)['stale']);self.assertEqual(case_assessment_summary(report)['status'],'review_recorded')
        self.assertIn('EXECUTIVE REVIEW / REVIEW RECORDED',pages(report)[0])
    def test_drafts_never_export_as_a_recorded_outcome(self):
        report=fixture();report['assessmentDraft']=report['assessmentLog'][-1];del report['assessmentLog']
        self.assertEqual(case_assessment_summary(report)['status'],'open');self.assertNotIn('EXECUTIVE REVIEW / REVIEW RECORDED',pages(report)[0])
    def test_malformed_or_oversized_history_refuses_silent_loss(self):
        for mutate in (lambda r:r['assessmentLog'].append({'status':'clear'}),lambda r:r.update(assessmentLog=r['assessmentLog']*501)):
            report=fixture();mutate(report)
            with self.assertRaises(ReportExportError):build_pdf(report)
    def test_original_report_remains_unchanged(self):
        report=fixture();old=copy.deepcopy(report);build_pdf(report);self.assertEqual(report,old)

if __name__=='__main__':
    if '--render' in sys.argv:
        for name,detail in (('current','brief'),('current','full'),('stale','brief')):
            report=fixture(name);report['reportDetail']=detail;(WORK/f'assessment-{name}-{detail}.pdf').write_bytes(build_pdf(report))
        print(WORK)
    else:unittest.main(verbosity=2)
